      "campo": "resolucao.antes.formulas",
      "depois": [
        "Equação de Gauss: 1 ÷ f = 1 ÷ p + 1 ÷ p'",
        "Espelho plano: distância da imagem ao plano = distância do objeto ao plano"
      ],
      "motivo": "Escreve as frações no padrão do guia e deixa a regra do espelho plano explícita."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["p", "distância do objeto O ao espelho esférico (30 cm)"],
        ["p'", "distância da imagem I1 ao espelho esférico; o apóstrofo indica 'da imagem'"],
        ["f", "distância focal: distância do foco ao espelho esférico (20 cm)"],
        ["D", "distância entre os dois espelhos (80 cm)"],
        ["X", "distância de I2 ao espelho esférico, o que a questão pede"],
        ["côncavo", "espelho curvo cuja parte refletora é a de dentro, como o interior de uma colher"],
        ["imagem real", "imagem formada onde os raios de luz realmente se cruzam"]
