    },
    {
      "campo": "resolucao.passos[1].porque",
      "depois": "A equação de Gauss liga f, p e p'. Para achar 1/p', passe 1/p para o outro lado e subtraia as frações, usando o denominador comum 60.",
      "motivo": "Explica de forma simples o porquê da subtração."
    },
    {
      "campo": "resolucao.passos[1].conta",
      "depois": "1/p' = 1/20 − 1/30 = 1/60",
